import java.io.File;
import java.io.RandomAccessFile;
import java.nio.MappedByteBuffer;
import java.nio.channels.FileChannel;

public class MemoryMappedFileDemo {
    public static void processFile(File file) throws Exception {
        try (RandomAccessFile raf = new RandomAccessFile(file, "rw");
             FileChannel channel = raf.getChannel()) {

            long size = channel.size();
            // Map the file into off-heap virtual memory
            MappedByteBuffer mappedBuffer = channel.map(FileChannel.MapMode.READ_WRITE, 0, size);

            // Modify data directly in off-heap memory space
            for (long i = 0; i < size; i++) {
                byte b = mappedBuffer.get((int) i);
                mappedBuffer.put((int) i, (byte)(b ^ 0xFF)); // Bitwise operation
            }

            // Force changes to be written to disk storage
            mappedBuffer.force();
        }
    }
}
